/**
 * Shared post shapes.
 *
 * Kept free of Node imports so client components can import the types without
 * pulling `fs`/`gray-matter` into the browser bundle. `posts.ts` (build-time,
 * reads content/posts via fs) and `posts-client.ts` (reads the generated JSON)
 * both re-export from here.
 */

export interface PostData {
  slug: string;
  title: string;
  date: string;
  summary: string;
  /** Plain-text body, generated by scripts/generate-posts.js for full-text search. */
  searchBody?: string;
  categories: string[];
  tags: string[];
  coverImage?: string;
  pinned?: boolean;
  draft?: boolean;
  series?: string;
  seriesOrder?: number;
}

export interface PostContent extends PostData {
  contentHtml: string;
}

/**
 * A series entry inside the generated index. Deliberately minimal — the series
 * view only renders the title and links by slug, so the full post object (and
 * its `searchBody`) is not duplicated here.
 */
export interface SeriesPost {
  slug: string;
  title: string;
  seriesOrder?: number;
}

export interface SeriesData {
  name: string;
  posts: SeriesPost[];
}
